+import items from './items.json' with {type:'json'};
+
+const DEFAULT_LIMIT = 2;
+const MIN_LIMIT = 1;
+const MAX_LIMIT = 5;
+
+export async function listTools() {
+  return [
+    {
+      name: 'catalog_search',
+      description: 'Search catalog items by name (case-insensitive) with pagination.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          query: { type: 'string', description: 'Substring to search for in item names.' },
+          offset: { type: 'integer', default: 0, description: 'Number of matching rows to skip.' },
+          limit: {
+            type: 'integer',
+            default: DEFAULT_LIMIT,
+            minimum: MIN_LIMIT,
+            maximum: MAX_LIMIT,
+            description: 'Maximum number of rows to return (1-5).'
+          }
+        },
+        required: ['query'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'catalog_search') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  const { query, offset = 0, limit = DEFAULT_LIMIT, ...rest } = args;
+
+  // Reject unexpected/extra arguments.
+  const extra = Object.keys(rest);
+  if (extra.length > 0) {
+    throw new Error(`Unexpected argument(s): ${extra.join(', ')}`);
+  }
+
+  // Validate query.
+  if (typeof query !== 'string') {
+    throw new Error('query must be a string');
+  }
+
+  // Validate offset.
+  if (!Number.isInteger(offset)) {
+    throw new Error('offset must be an integer');
+  }
+  if (offset < 0) {
+    throw new Error('offset must be >= 0');
+  }
+
+  // Validate limit.
+  if (!Number.isInteger(limit)) {
+    throw new Error('limit must be an integer');
+  }
+  if (limit < MIN_LIMIT || limit > MAX_LIMIT) {
+    throw new Error(`limit must be between ${MIN_LIMIT} and ${MAX_LIMIT}`);
+  }
+
+  const needle = query.toLowerCase();
+  const matches = items.filter((it) => it.name.toLowerCase().includes(needle));
+  const page = matches.slice(offset, offset + limit);
+
+  const result = { results: page };
+  if (offset + limit < matches.length) {
+    result.next_offset = offset + limit;
+  }
+
+  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
+}
